class Vehicle {
    protected String registrationNumber;
    protected int maximumSpeed;

    public Vehicle(String reg, int maxSpeed) {
        this.registrationNumber = reg;
        this.maximumSpeed = maxSpeed;
    }

    public void displaySpecs() {
        System.out.println("Registration: " + registrationNumber + ", Max Speed: " + maximumSpeed + " km/h");
    }
}

// Car specializes Vehicle with passenger count
class Car extends Vehicle {
    private int seatingCapacity;

    public Car(String reg, int maxSpeed, int seats) {
        super(reg, maxSpeed);
        this.seatingCapacity = seats;
    }

    public void displayCarDetails() {
        displaySpecs(); // Call inherited superclass method
        System.out.println("Seating Capacity: " + seatingCapacity + " passengers");
    }
}

public class TaxonomyDemo {
    public static void main(String[] args) {
        Car sedan = new Car("KA-01-AB-1234", 180, 5);
        sedan.displayCarDetails();
    }
}

