class ParentEntity {
    protected int parentField = 100;
}

class ChildEntity extends ParentEntity {
    protected int childField = 200;

    public void showAllFields() {
        // Both parentField and childField exist within the single 'this' heap object
        System.out.println("parentField: " + parentField);
        System.out.println("childField: " + childField);
    }
}

public class MemoryDemo {
    public static void main(String[] args) {
        ChildEntity obj = new ChildEntity();
        obj.showAllFields();
    }
