class Room {
    protected String roomType;
    public Room(String roomType) { this.roomType = roomType; }
}

class Building {
    protected String address;
    public Building(String address) { this.address = address; }
}

class House extends Building {
    private Room primaryRoom;

    public House(String address, Room room) {
        super(address);
        this.primaryRoom = room;
    }

    public void display() {
        System.out.println("Building at " + address + " with " + primaryRoom.roomType);
    }
}

public class Main {
    public static void main(String[] args) {
        House h = new House("101 Main St", new Room("Living Room"));
        h.display();
    }
}

class Patient {
    protected String patientId;
    protected String name;
    protected double baseConsultationFee;

    public Patient(String patientId, String name, double baseFee) {
        this.patientId = patientId;
        this.name = name;
        this.baseFee = baseFee;
    }
}

class Inpatient extends Patient {
    private String roomNumber;
    private int daysAdmitted;
    private double dailyRoomRate;

    public Inpatient(String patientId, String name, double baseFee, String roomNumber, int days, double dailyRate) {
        super(patientId, name, baseFee);
        this.roomNumber = roomNumber;
        this.daysAdmitted = days;
        this.dailyRoomRate = dailyRate;
    }

    public double calculateTotalBill() {
        return baseFee + (daysAdmitted * dailyRoomRate);
    }

    public void printInvoice() {
        System.out.println("Patient " + patientId + " (" + name + ") Total Bill: $" + calculateTotalBill() + " (Admitted in Room " + roomNumber + " for " + daysAdmitted + " days)");
    }
}

public class Main {
    public static void main(String[] args) {
        Inpatient p = new Inpatient("P-702", "John Doe", 250.0, "304B", 4, 600.0);
        p.printInvoice();
    }
}
